#include <bits/stdc++.h>using namespace std; int solve(string a, string b) {    int n = a.size(), m = b.size();    int maxLen = 0;     // try all substrings of a    for(int i = 0; i < n; i++){        for(int j = i; j < n; j++){            string sub = a.substr(i, j - i + 1);             // check if substring exists in b            if(b.find(sub) != string::npos){                maxLen = max(maxLen, (int)sub.size());            }        }    }     return n + m - 2 * maxLen;} int main(){    ios::sync_with_stdio(false);    cin.tie(nullptr);     int t;    cin >> t;    while(t--){        string a, b;        cin >> a >> b;         cout << solve(a, b) << "\n";    }     return 0;}